{
  "findings": [
    {
      "check_id": "CKV_AWS_24",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 22",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "Allowing ingress from 0.0.0.0/0 to port 22 exposes the server to potential brute-force attacks from any IP address."
    },
    {
      "check_id": "CKV_AWS_25",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 3389",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "Allowing ingress from 0.0.0.0/0 to port 3389 exposes the server to potential brute-force attacks from any IP address."
    },
    {
      "check_id": "CKV_AWS_260",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 80",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "Allowing ingress from 0.0.0.0/0 to port 80 exposes the server to potential HTTP-based attacks from any IP address."
    },
    {
      "check_id": "CKV_AWS_277",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "Allowing ingress from 0.0.0.0/0 to all ports (-1) exposes the server to potential attacks on any open port from any IP address."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"vault\" {\n  name        = \"vault\"\n  description = \"Ingress for Vault\"\n  vpc_id      = aws_vpc.my_vpc.id\n  dynamic \"ingress\" {\n    iterator = port\n    for_each = var.ingress_ports\n    content {\n      from_port   = port.value\n      to_port     = port.value\n      protocol    = \"tcp\"\n      cidr_blocks = var.allowed_cidr_blocks\n    }\n  }\n}\n\nvariable \"allowed_cidr_blocks\" {\n  description = \"List of allowed CIDR blocks for ingress rules\"\n  type        = list(string)\n  default     = []\n}",
  "fix_summary": "Replaced the hardcoded '0.0.0.0/0' CIDR block with a variable 'allowed_cidr_blocks' to restrict ingress traffic to explicitly defined IP ranges."
}
